import type media from "@/content/media.json";

/** A slot generated by `pnpm images` (src/content/media.json). Missing visuals are `null` → <Placeholder>. */
export type MediaSlot = keyof typeof media;

export type MediaEntry = {
  src: string;
  width: number;
  height: number;
  alt: string;
  blurDataURL: string;
  color: string;
};

export type SectionTheme = "paper" | "mist" | "ink";

export type Cta = { label: string; href: string };

/** A visual that is not available yet: rendered as <Placeholder> in dev/preview, fails a production build. */
export type MissingVisual = { placeholder: string; ratio: `${number}/${number}` };

export type Step = { title: string; text: string };

export type FaqItem = { question: string; answer: string };
